{
  "name": "AI Scout - Personal Research Agent",
  "description": "Ein automatisierter Agent, der Deep Research zu einer Liste von KI-Experten durchführt, Neuigkeiten aggregiert und einen kuratierten Newsletter erstellt."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Expert {
  id: string;
  name: string;
  role: string;
  topics: string[];
  twitterHandle?: string;
  active: boolean;
}

export interface ReportItem {
  headline: string;
  summary: string;
  sourceUrl: string;
  sourceType: 'Twitter' | 'Paper' | 'Video' | 'Podcast' | 'News' | 'Other';
  expertName: string;
  date: string;
}

export interface Report {
  id: string;
  createdAt: string;
  title: string;
  intro: string;
  items: ReportItem[];
  actionSteps: string[];
  rawMarkdown: string; // Keep the raw output just in case
}

export interface AppState {
  experts: Expert[];
  reports: Report[];
  isGenerating: boolean;
  progressMessage: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Expert, Report } from '../types';

// Initialize Gemini
// NOTE: We recreate the client inside the function to ensure we get the latest key if it changes, 
// though typically env vars are static. For this architecture, we use process.env.
const getClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateResearchReport = async (
  experts: Expert[],
  onProgress: (msg: string) => void
): Promise<Report> => {
  const ai = getClient();
  const activeExperts = experts.filter(e => e.active);
  const expertNames = activeExperts.map(e => `${e.name} (${e.role})`).join(", ");

  onProgress("Starte Deep Research Agent...");

  // We use the Pro model for deep reasoning and search integration
  const modelId = "gemini-3-pro-preview";

  const systemPrompt = `
    Du bist ein erstklassiger KI-Forschungs-Assistent. Deine Aufgabe ist es, einen "Deep Research" über die aktuellen Aktivitäten führender KI-Experten durchzuführen.

    ZIEL: Erstelle einen kuratierten Newsletter (Digest) über die wichtigsten Neuigkeiten der letzten 7 Tage.

    QUELLEN: Suche nach:
    1. Neuen Forschungsarbeiten (Papers)
    2. Wichtigen Social Media Beiträgen (Twitter/X, LinkedIn)
    3. Podcast-Auftritten oder Youtube-Videos
    4. Offiziellen Blog-Posts

    EXPERTEN-LISTE: ${expertNames}

    OUTPUT FORMAT (JSON):
    Du musst ein JSON-Objekt zurückgeben, das strikt dem Schema folgt. 
    Wichtig: Ignoriere Rauschen. Konzentriere dich auf Substanz (neue Modelle, Sicherheitswarnungen, Durchbrüche, Kontroversen).

    Sprache: Der Inhalt (Headlines, Zusammenfassungen) muss auf DEUTSCH sein.
  `;

  const userPrompt = `Suche nach den neuesten Aktivitäten (letzte 3-7 Tage) der genannten Experten. Fasse die wichtigsten 5-10 Erkenntnisse zusammen und leite daraus konkrete 'Action Steps' ab, wie man als AI-Engineer darauf reagieren sollte.`;

  onProgress("Durchsuche das Web nach Beiträgen, Papers und Videos...");

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: userPrompt,
      config: {
        systemInstruction: systemPrompt,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Ein fesselnder Titel für den Newsletter, z.B. 'KI Update: [Datum]'" },
            intro: { type: Type.STRING, description: "Eine kurze Einleitung (Editorial), die die Stimmung der Woche zusammenfasst." },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  headline: { type: Type.STRING },
                  summary: { type: Type.STRING, description: "2-3 Sätze Zusammenfassung des Inhalts." },
                  sourceUrl: { type: Type.STRING },
                  sourceType: { type: Type.STRING, enum: ["Twitter", "Paper", "Video", "Podcast", "News", "Other"] },
                  expertName: { type: Type.STRING },
                  date: { type: Type.STRING, description: "Format YYYY-MM-DD" }
                },
                required: ["headline", "summary", "sourceType", "expertName"]
              }
            },
            actionSteps: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "3-4 konkrete Handlungsempfehlungen oder Lernziele basierend auf den News."
            }
          },
          required: ["title", "intro", "items", "actionSteps"]
        }
      }
    });

    onProgress("Verarbeite Ergebnisse und generiere Report...");

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText);

    // Add explicit URLs from grounding if missing in JSON (Best effort merge)
    // Often the model puts the URL in the JSON, but sometimes we want to verify against chunks.
    // For simplicity in this demo, we trust the model's JSON extraction skills which are high in Gemini 1.5 Pro/Flash.

    const report: Report = {
      id: crypto.randomUUID(),
      createdAt: new Date().toISOString(),
      title: data.title || "Weekly AI Digest",
      intro: data.intro || "Hier ist dein Update.",
      items: data.items || [],
      actionSteps: data.actionSteps || [],
      rawMarkdown: "N/A" // Legacy field
    };

    onProgress("Fertig!");
    return report;

  } catch (error) {
    console.error("Gemini Error:", error);
    onProgress("Fehler beim Abrufen der Daten.");
    throw error;
  }
};

import React, { useState } from 'react';
import { Expert } from '../types';
import { Trash2, Plus, User, CheckCircle, Circle } from 'lucide-react';

interface ExpertListProps {
  experts: Expert[];
  setExperts: (experts: Expert[]) => void;
}

export const ExpertList: React.FC<ExpertListProps> = ({ experts, setExperts }) => {
  const [newExpertName, setNewExpertName] = useState('');
  const [newExpertRole, setNewExpertRole] = useState('');

  const toggleActive = (id: string) => {
    setExperts(experts.map(e => e.id === id ? { ...e, active: !e.active } : e));
  };

  const removeExpert = (id: string) => {
    setExperts(experts.filter(e => e.id !== id));
  };

  const addExpert = () => {
    if (!newExpertName.trim()) return;
    const newExpert: Expert = {
      id: crypto.randomUUID(),
      name: newExpertName,
      role: newExpertRole || 'Forscher',
      topics: [],
      active: true
    };
    setExperts([...experts, newExpert]);
    setNewExpertName('');
    setNewExpertRole('');
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
      <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
        <User className="w-5 h-5 text-brand-600" />
        Überwachte Experten ({experts.filter(e => e.active).length}/{experts.length})
      </h2>

      <p className="text-sm text-slate-500 mb-6">
        Der Agent sucht nach Aktivitäten dieser Personen. Deaktiviere Personen, um sie im nächsten Suchlauf zu ignorieren.
      </p>

      <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 mb-6 scrollbar-thin scrollbar-thumb-slate-300">
        {experts.map((expert) => (
          <div key={expert.id} className={`flex items-center justify-between p-3 rounded-lg border ${expert.active ? 'border-brand-200 bg-brand-50' : 'border-slate-100 bg-slate-50'}`}>
            <div className="flex items-center gap-3">
              <button onClick={() => toggleActive(expert.id)} className="text-slate-400 hover:text-brand-600 transition-colors">
                {expert.active ? <CheckCircle className="w-5 h-5 text-brand-600" /> : <Circle className="w-5 h-5" />}
              </button>
              <div>
                <div className={`font-medium ${expert.active ? 'text-slate-900' : 'text-slate-400'}`}>{expert.name}</div>
                <div className="text-xs text-slate-500">{expert.role}</div>
              </div>
            </div>
            <button onClick={() => removeExpert(expert.id)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors">
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        ))}
      </div>

      <div className="flex flex-col sm:flex-row gap-2 pt-4 border-t border-slate-100">
        <input
          type="text"
          placeholder="Name (z.B. Lex Fridman)"
          className="flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-brand-500"
          value={newExpertName}
          onChange={(e) => setNewExpertName(e.target.value)}
        />
        <input
          type="text"
          placeholder="Rolle (Optional)"
          className="flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-brand-500"
          value={newExpertRole}
          onChange={(e) => setNewExpertRole(e.target.value)}
        />
        <button 
          onClick={addExpert}
          className="bg-slate-900 hover:bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center justify-center gap-2 transition-colors"
        >
          <Plus className="w-4 h-4" />
          Hinzufügen
        </button>
      </div>
    </div>
  );
};

import React, { useRef } from 'react';
import { Report } from '../types';
import { Share2, Download, Copy, ExternalLink, Calendar } from 'lucide-react';

interface NewsletterProps {
  report: Report;
}

export const Newsletter: React.FC<NewsletterProps> = ({ report }) => {
  const contentRef = useRef<HTMLDivElement>(null);

  const copyToClipboard = () => {
    if (contentRef.current) {
      const html = contentRef.current.innerHTML;
      const blob = new Blob([html], { type: 'text/html' });
      const item = new ClipboardItem({ 'text/html': blob });
      navigator.clipboard.write([item]).then(() => {
        alert("Newsletter HTML in die Zwischenablage kopiert! Du kannst ihn jetzt in eine E-Mail einfügen.");
      });
    }
  };

  const handleMailTo = () => {
    const subject = encodeURIComponent(report.title);
    const body = encodeURIComponent(`Hier ist dein KI-Update:\n\n${report.intro}\n\nSchaue dir den vollständigen Bericht im Dashboard an.`);
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
      {/* Toolbar */}
      <div className="bg-slate-50 border-b border-slate-200 p-4 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-2 text-slate-500 text-sm">
          <Calendar className="w-4 h-4" />
          {new Date(report.createdAt).toLocaleDateString('de-DE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
        </div>
        <div className="flex gap-2">
          <button onClick={copyToClipboard} className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded hover:bg-slate-50 transition-colors">
            <Copy className="w-4 h-4" />
            HTML Kopieren
          </button>
          <button onClick={handleMailTo} className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-white bg-brand-600 rounded hover:bg-brand-700 transition-colors">
            <Share2 className="w-4 h-4" />
            Per E-Mail senden
          </button>
        </div>
      </div>

      {/* Content */}
      <div ref={contentRef} className="p-8 max-w-4xl mx-auto">
        <div className="mb-8 border-b-4 border-brand-500 pb-6">
          <h1 className="text-4xl font-serif font-bold text-slate-900 mb-4">{report.title}</h1>
          <p className="text-lg text-slate-600 italic leading-relaxed font-serif">
            {report.intro}
          </p>
        </div>

        <div className="space-y-10">
          {/* Main News Items */}
          <section>
            <h2 className="text-sm font-bold tracking-wider text-slate-400 uppercase mb-6">Wichtige Updates</h2>
            <div className="grid gap-8">
              {report.items.map((item, idx) => (
                <article key={idx} className="flex flex-col md:flex-row gap-6 group">
                  <div className="md:w-1/4 pt-1">
                     <span className="inline-block px-2 py-1 text-xs font-bold bg-slate-100 text-slate-600 rounded uppercase tracking-wide">
                        {item.sourceType}
                     </span>
                     <div className="mt-2 font-medium text-brand-600">{item.expertName}</div>
                     <div className="text-xs text-slate-400 mt-1">{item.date}</div>
                  </div>
                  <div className="md:w-3/4">
                    <h3 className="text-xl font-bold text-slate-900 mb-2 group-hover:text-brand-600 transition-colors">
                      <a href={item.sourceUrl || '#'} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2">
                        {item.headline}
                        {item.sourceUrl && <ExternalLink className="w-4 h-4 opacity-50" />}
                      </a>
                    </h3>
                    <p className="text-slate-600 leading-relaxed">
                      {item.summary}
                    </p>
                  </div>
                </article>
              ))}
            </div>
          </section>

          {/* Action Steps */}
          {report.actionSteps.length > 0 && (
            <section className="bg-slate-50 rounded-xl p-6 border border-slate-100">
              <h2 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                <span className="w-2 h-6 bg-brand-500 rounded-full"></span>
                Action Steps & Takeaways
              </h2>
              <ul className="space-y-3">
                {report.actionSteps.map((step, idx) => (
                  <li key={idx} className="flex items-start gap-3 text-slate-700">
                    <span className="flex-shrink-0 w-6 h-6 rounded-full bg-brand-100 text-brand-700 flex items-center justify-center font-bold text-xs mt-0.5">
                      {idx + 1}
                    </span>
                    <span>{step}</span>
                  </li>
                ))}
              </ul>
            </section>
          )}
        </div>

        <div className="mt-12 pt-8 border-t border-slate-200 text-center text-slate-400 text-sm">
          Erstellt von deinem AI Scout Agenten am {new Date().toLocaleDateString('de-DE')}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ExpertList } from './components/ExpertList';
import { Newsletter } from './components/Newsletter';
import { generateResearchReport } from './services/geminiService';
import { Expert, Report, AppState } from './types';
import { INITIAL_EXPERTS } from './constants';
import { Bot, History, Sparkles, AlertCircle, Play } from 'lucide-react';

// Simple persistence helper
const loadState = (): AppState => {
  const saved = localStorage.getItem('ai_scout_state_v1');
  if (saved) {
    return JSON.parse(saved);
  }
  return {
    experts: INITIAL_EXPERTS,
    reports: [],
    isGenerating: false,
    progressMessage: ''
  };
};

export default function App() {
  const [state, setState] = useState<AppState>(loadState());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'experts' | 'archive'>('dashboard');

  // Persist state changes
  useEffect(() => {
    localStorage.setItem('ai_scout_state_v1', JSON.stringify(state));
  }, [state]);

  const handleUpdateExperts = (experts: Expert[]) => {
    setState(prev => ({ ...prev, experts }));
  };

  const handleRunResearch = async () => {
    if (state.isGenerating) return;

    setState(prev => ({ ...prev, isGenerating: true, progressMessage: 'Initialisiere...' }));

    try {
      const report = await generateResearchReport(state.experts, (msg) => {
        setState(prev => ({ ...prev, progressMessage: msg }));
      });

      setState(prev => ({
        ...prev,
        isGenerating: false,
        reports: [report, ...prev.reports]
      }));
      setActiveTab('dashboard');
    } catch (e) {
      setState(prev => ({
        ...prev,
        isGenerating: false,
        progressMessage: 'Fehler aufgetreten.'
      }));
      alert("Es gab ein Problem bei der Recherche. Bitte überprüfe deinen API Key oder versuche es später noch einmal.");
    }
  };

  const latestReport = state.reports[0];

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900 font-sans">
      {/* Header */}
      <header className="bg-slate-900 text-white sticky top-0 z-50 shadow-md">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-brand-500 rounded-lg flex items-center justify-center">
              <Bot className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-lg tracking-tight">AI Scout</span>
          </div>

          <nav className="flex gap-1">
            <button 
              onClick={() => setActiveTab('dashboard')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'dashboard' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Dashboard
            </button>
            <button 
              onClick={() => setActiveTab('experts')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'experts' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Experten Liste
            </button>
            <button 
              onClick={() => setActiveTab('archive')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'archive' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Archiv
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8">

        {/* Progress Overlay */}
        {state.isGenerating && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center z-[100] text-white">
            <div className="w-16 h-16 border-4 border-brand-500 border-t-transparent rounded-full animate-spin mb-6"></div>
            <h2 className="text-2xl font-bold mb-2">Deep Research läuft...</h2>
            <p className="text-slate-300 animate-pulse">{state.progressMessage}</p>
            <div className="mt-8 max-w-md text-center text-sm text-slate-400">
              Der Agent scannt Papers, Social Media und News. Dies kann bis zu 60 Sekunden dauern.
            </div>
          </div>
        )}

        {/* Dashboard View */}
        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            {/* Action Bar */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <div>
                <h1 className="text-2xl font-bold text-slate-900">Willkommen zurück.</h1>
                <p className="text-slate-500">
                  Du überwachst {state.experts.filter(e => e.active).length} Experten.
                  {latestReport && ` Letztes Update: ${new Date(latestReport.createdAt).toLocaleDateString()}`}
                </p>
              </div>
              <button 
                onClick={handleRunResearch}
                disabled={state.isGenerating}
                className="bg-brand-600 hover:bg-brand-700 disabled:bg-slate-400 text-white px-6 py-3 rounded-xl font-bold text-lg shadow-lg hover:shadow-brand-500/30 transition-all flex items-center gap-3"
              >
                {state.isGenerating ? (
                  <>Recherchiere...</>
                ) : (
                  <>
                    <Sparkles className="w-5 h-5" />
                    Deep Research starten
                  </>
                )}
              </button>
            </div>

            {/* Hint about Cron Job */}
            <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 flex gap-3">
              <AlertCircle className="w-5 h-5 text-blue-600 flex-shrink-0" />
              <div className="text-sm text-blue-800">
                <strong>Automatisierungs-Hinweis:</strong> Da dies eine Web-App im Browser ist, kann sie nicht im Hintergrund laufen, wenn der Tab geschlossen ist. Um den "Newsletter" zu erhalten, öffne diese Seite einfach 2-3 mal die Woche und klicke auf "Deep Research starten".
              </div>
            </div>

            {/* Latest Report */}
            {latestReport ? (
              <Newsletter report={latestReport} />
            ) : (
              <div className="text-center py-20 bg-white rounded-xl border border-dashed border-slate-300">
                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-slate-100 mb-4">
                  <Play className="w-8 h-8 text-slate-400 ml-1" />
                </div>
                <h3 className="text-xl font-medium text-slate-900 mb-2">Noch kein Bericht vorhanden</h3>
                <p className="text-slate-500 max-w-md mx-auto mb-6">
                  Starte deinen ersten Deep Research, um die neuesten Updates der KI-Welt zu erhalten.
                </p>
                <button onClick={handleRunResearch} className="text-brand-600 font-medium hover:underline">
                  Jetzt Suche starten
                </button>
              </div>
            )}
          </div>
        )}

        {/* Experts Tab */}
        {activeTab === 'experts' && (
          <div className="max-w-3xl mx-auto">
            <ExpertList experts={state.experts} setExperts={handleUpdateExperts} />
          </div>
        )}

        {/* Archive Tab */}
        {activeTab === 'archive' && (
          <div className="space-y-6">
             <h2 className="text-2xl font-bold flex items-center gap-2">
                <History className="w-6 h-6" />
                Report Archiv
             </h2>
             {state.reports.length === 0 && <p className="text-slate-500">Keine Berichte gespeichert.</p>}
             <div className="grid gap-4">
               {state.reports.map((report) => (
                 <div key={report.id} className="bg-white p-5 rounded-lg border border-slate-200 hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-start">
                      <div>
                        <h3 className="font-bold text-lg text-slate-900">{report.title}</h3>
                        <p className="text-slate-500 text-sm mt-1">
                          {new Date(report.createdAt).toLocaleDateString('de-DE', { dateStyle: 'full', timeStyle: 'short' })}
                        </p>
                        <p className="text-slate-600 mt-3 line-clamp-2">{report.intro}</p>
                      </div>
                      <button 
                        onClick={() => {
                          // Move report to top and switch view
                          const otherReports = state.reports.filter(r => r.id !== report.id);
                          setState(prev => ({...prev, reports: [report, ...otherReports]}));
                          setActiveTab('dashboard');
                        }}
                        className="text-brand-600 font-medium text-sm hover:underline"
                      >
                        Anzeigen
                      </button>
                    </div>
                 </div>
               ))}
             </div>
          </div>
        )}

      </main>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ExpertList } from './components/ExpertList';
import { Newsletter } from './components/Newsletter';
import { generateResearchReport } from './services/geminiService';
import { Expert, Report, AppState } from './types';
import { INITIAL_EXPERTS } from './constants';
import { Bot, History, Sparkles, AlertCircle, Play, CalendarClock } from 'lucide-react';

// Simple persistence helper
const loadState = (): AppState => {
  const saved = localStorage.getItem('ai_scout_state_v1');
  if (saved) {
    const parsed = JSON.parse(saved);
    // Ensure new CSV experts are loaded if user has old local state
    // In a real app we might merge, here we check if experts array is empty or small mismatch
    // But for this demo, let's keep user state if valid, or reset if they want new data
    // We will just return parsed state. To force update, user can clear storage or we add a version check.
    // For this specific update request, we want to ensure the NEW list is used if the user hasn't customized much.
    // Let's rely on the user manually updating via UI or if the array is empty.
    if (!parsed.experts || parsed.experts.length === 0) {
        parsed.experts = INITIAL_EXPERTS;
    }
    return parsed;
  }
  return {
    experts: INITIAL_EXPERTS,
    reports: [],
    isGenerating: false,
    progressMessage: ''
  };
};

export default function App() {
  const [state, setState] = useState<AppState>(loadState());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'experts' | 'archive'>('dashboard');

  // Persist state changes
  useEffect(() => {
    localStorage.setItem('ai_scout_state_v1', JSON.stringify(state));
  }, [state]);

  // If the user has old initial data in local storage, they won't see the new CSV list.
  // We add a one-time "reset to default" button in experts tab or handle it via a version migration in a real app.
  // For now, let's assume if the count is different from our CSV (21), we might prompt or just leave it.

  const handleUpdateExperts = (experts: Expert[]) => {
    setState(prev => ({ ...prev, experts }));
  };

  const handleResetExperts = () => {
    if(confirm("Dies setzt deine Expertenliste auf die Standard-Liste (21 Forscher) zurück. Deine eigenen Änderungen gehen verloren. Fortfahren?")) {
        setState(prev => ({ ...prev, experts: INITIAL_EXPERTS }));
    }
  }

  const handleRunResearch = async () => {
    if (state.isGenerating) return;

    setState(prev => ({ ...prev, isGenerating: true, progressMessage: 'Initialisiere...' }));

    try {
      const report = await generateResearchReport(state.experts, (msg) => {
        setState(prev => ({ ...prev, progressMessage: msg }));
      });

      setState(prev => ({
        ...prev,
        isGenerating: false,
        reports: [report, ...prev.reports]
      }));
      setActiveTab('dashboard');
    } catch (e) {
      setState(prev => ({
        ...prev,
        isGenerating: false,
        progressMessage: 'Fehler aufgetreten.'
      }));
      alert("Es gab ein Problem bei der Recherche. Bitte überprüfe deinen API Key oder versuche es später noch einmal.");
    }
  };

  const latestReport = state.reports[0];

  // Check if report is due (older than 2 days)
  const isUpdateDue = !latestReport || (Date.now() - new Date(latestReport.createdAt).getTime()) > (1000 * 60 * 60 * 24 * 2);

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900 font-sans">
      {/* Header */}
      <header className="bg-slate-900 text-white sticky top-0 z-50 shadow-md">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-brand-500 rounded-lg flex items-center justify-center">
              <Bot className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-lg tracking-tight">AI Scout</span>
          </div>

          <nav className="flex gap-1">
            <button 
              onClick={() => setActiveTab('dashboard')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'dashboard' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Dashboard
            </button>
            <button 
              onClick={() => setActiveTab('experts')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'experts' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Experten ({state.experts.length})
            </button>
            <button 
              onClick={() => setActiveTab('archive')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'archive' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Archiv
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8">

        {/* Progress Overlay */}
        {state.isGenerating && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center z-[100] text-white">
            <div className="w-16 h-16 border-4 border-brand-500 border-t-transparent rounded-full animate-spin mb-6"></div>
            <h2 className="text-2xl font-bold mb-2">Deep Research läuft...</h2>
            <p className="text-slate-300 animate-pulse">{state.progressMessage}</p>
            <div className="mt-8 max-w-md text-center text-sm text-slate-400">
              Der Agent scannt Papers, Social Media und News der {state.experts.filter(e => e.active).length} Experten. Dies kann bis zu 60 Sekunden dauern.
            </div>
          </div>
        )}

        {/* Dashboard View */}
        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            {/* Status / Action Bar */}
            <div className={`flex flex-col md:flex-row md:items-center justify-between gap-6 p-6 rounded-xl border shadow-sm ${isUpdateDue ? 'bg-amber-50 border-amber-200' : 'bg-white border-slate-200'}`}>
              <div>
                <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                  {isUpdateDue ? (
                    <>
                      <CalendarClock className="w-6 h-6 text-amber-600" />
