import { GoogleGenAI, Type } from "@google/genai";
import { Expert, Report } from '../types';

// Initialize Gemini
const getClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateResearchReport = async (
  experts: Expert[],
  onProgress: (msg: string) => void
): Promise<Report> => {
  const ai = getClient();
  const activeExperts = experts.filter(e => e.active);
  const expertNames = activeExperts.map(e => `${e.name} (${e.role})`).join(", ");

  onProgress("Analysiere Schulentwicklungs-Kontext...");

  // We use the Pro model for deep reasoning and search integration
  const modelId = "gemini-3-pro-preview";

  const systemPrompt = `
    Du bist ein strategischer KI-Berater für einen **Lehrer, IT-Koordinator und Mitglied der erweiterten Schulleitung** an einer Gesamtschule in Niedersachsen.

    DEIN NUTZER:
    - Arbeitet an Schulentwicklungsprozessen und IT-Infrastruktur.
    - Möchte sich für höhere Führungsaufgaben qualifizieren.
    - Interessiert sich für: Wandel von Unterricht, KI-Einfluss auf Bildung, Future Skills für Schüler, ethische Implikationen.

    DEINE AUFGABE:
    Führe einen "Deep Research" zu den genannten KI-Experten durch.

    SUCH-STRATEGIE (DEEP SEARCH):
    Suche nicht nur nach direkten Posts der Experten, sondern auch:
    1. Wo wurden sie **zitiert** oder diskutiert? (Rezeption in der Fachwelt)
    2. Interviews in Podcasts (via Show Notes/Transkripte) oder YouTube.
    3. Neue Papers (Arxiv) oder News-Artikel über sie.
    4. Wenn ein Experte nichts gesagt hat, suche nach Diskussionen *über* seine Thesen.

    OUTPUT FORMAT (JSON):
    Erstelle einen JSON-Output für einen Newsletter.

    REGELN FÜR INHALTE:
    - Filtere reinen Tech-Hype heraus.
    - Fokussiere auf Implikationen für **Bildung, Gesellschaft und Schule**.
    - Beispiel: Wenn Sam Altman über "Compute" spricht -> Was bedeutet das für die Verfügbarkeit von KI an Schulen?

    ACTION STEPS (WICHTIG):
    Die "Action Steps" müssen sich strikt an den User (Schulleitung/IT) richten. 
    Beispiele: "Diskutiere im Kollegium...", "Prüfe die IT-Infrastruktur auf...", "Nutze dieses Argument für die Schulentwicklungs-Sitzung...", "Zur eigenen Profilierung: Verfasse ein Papier zu...".
  `;

  const userPrompt = `
    Experten-Liste: ${expertNames}

    Suche nach Aktivitäten der letzten 3-7 Tage. 
    Berücksichtige Social Media (X, LinkedIn, Bluesky), News, Papers, Podcast-Erwähnungen und YouTube-Auftritte.

    Erstelle 5-8 hochrelevante News-Items und 3-4 strategische Action-Steps für meine Rolle als Schulleiter/IT-Koordinator.
  `;

  onProgress("Durchsuche das Web (Social, News, Papers, Podcasts)...");

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: userPrompt,
      config: {
        systemInstruction: systemPrompt,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Titel, z.B. 'KI & Bildung Update: [Datum]'" },
            intro: { type: Type.STRING, description: "Editorial aus Sicht eines Bildungs-Strategen." },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  headline: { type: Type.STRING },
                  summary: { type: Type.STRING, description: "Zusammenfassung mit Fokus auf Bildungs-Relevanz." },
                  sourceUrl: { type: Type.STRING },
                  sourceType: { type: Type.STRING, enum: ["Twitter/X", "Paper", "Video/YouTube", "Podcast", "News", "LinkedIn", "Andere"] },
                  expertName: { type: Type.STRING },
                  date: { type: Type.STRING, description: "YYYY-MM-DD" }
                },
                required: ["headline", "summary", "sourceType", "expertName"]
              }
            },
            actionSteps: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "Konkrete Schritte für Schulentwicklung/IT-Koordination."
            }
          },
          required: ["title", "intro", "items", "actionSteps"]
        }
      }
    });

    onProgress("Generiere Strategie-Report...");

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText);

    const report: Report = {
      id: crypto.randomUUID(),
      createdAt: new Date().toISOString(),
      title: data.title || "Weekly AI Education Digest",
      intro: data.intro || "Hier ist dein Update für die Schulentwicklung.",
      items: data.items || [],
      actionSteps: data.actionSteps || [],
      rawMarkdown: "N/A"
    };

    onProgress("Fertig!");
    return report;

  } catch (error) {
    console.error("Gemini Error:", error);
    onProgress("Fehler beim Abrufen der Daten.");
    throw error;
  }
};

import React, { useRef } from 'react';
import { Report } from '../types';
import { Share2, Download, Copy, ExternalLink, Calendar, Radio, Newspaper, Youtube, FileText, MessageSquare, Mic } from 'lucide-react';

interface NewsletterProps {
  report: Report;
