        </div>

        <div className="space-y-10">
          {/* Main News Items */}
          <section>
            <h2 className="text-sm font-bold tracking-wider text-slate-400 uppercase mb-6">Wichtige Updates</h2>
            <div className="grid gap-8">
              {report.items.map((item, idx) => (
                <article key={idx} className="flex flex-col md:flex-row gap-6 group">
                  {/* Left Column: Expert Info */}
                  <div className="md:w-1/4 pt-1 flex flex-col gap-1">
                     <div className="font-bold text-brand-700 text-lg leading-tight">
                        {item.expertName}
                     </div>
                     <div className="text-sm text-slate-400 mb-2">
                        {new Date(item.date).toLocaleDateString('de-DE')}
