                     <div>
                       <span className="inline-flex items-center gap-1.5 px-2.5 py-1 text-xs font-semibold bg-slate-100 text-slate-600 rounded-full border border-slate-200 uppercase tracking-wide">
                          {getSourceIcon(item.sourceType)}
                          {item.sourceType}
                       </span>
                     </div>
                  </div>

                  {/* Right Column: Content */}
                  <div className="md:w-3/4">
                    <h3 className="text-xl font-bold text-slate-900 mb-2 group-hover:text-brand-600 transition-colors font-serif">
                      <a href={item.sourceUrl || '#'} target="_blank" rel="noopener noreferrer" className="flex items-start gap-2">
