import React, { useState, useMemo } from 'react';
import { Report, Expert } from '../types';
import { Search, Filter, Calendar, ExternalLink, FileText, User, ChevronDown, TrendingUp } from 'lucide-react';

interface KnowledgeBaseProps {
  reports: Report[];
  experts: Expert[];
}

type ViewMode = 'insights' | 'strategy';

export const KnowledgeBase: React.FC<KnowledgeBaseProps> = ({ reports, experts }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedExpertId, setSelectedExpertId] = useState<string>('all');
  const [viewMode, setViewMode] = useState<ViewMode>('insights');

  // Flatten and process data
  const { allItems, allStrategies } = useMemo(() => {
    const items = reports.flatMap(report => 
      report.items.map(item => ({ ...item, reportTitle: report.title }))
    ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const strategies = reports.flatMap(report => 
      report.actionSteps.map(step => ({ 
        text: step, 
        date: report.createdAt, 
        reportTitle: report.title,
        reportId: report.id
      }))
    ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return { allItems: items, allStrategies: strategies };
  }, [reports]);

  // Filter Logic
  const filteredItems = allItems.filter(item => {
    const matchesSearch = 
      item.headline.toLowerCase().includes(searchTerm.toLowerCase()) || 
      item.summary.toLowerCase().includes(searchTerm.toLowerCase());

    let matchesExpert = true;
    if (selectedExpertId !== 'all') {
      const expert = experts.find(e => e.id === selectedExpertId);
      if (expert) {
        // Loose matching because report might have "Name (Role)" or just "Name"
        matchesExpert = item.expertName.toLowerCase().includes(expert.name.toLowerCase());
      }
    }

    return matchesSearch && matchesExpert;
  });

  const filteredStrategies = allStrategies.filter(step => 
    step.text.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
        <div>
          <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
            <TrendingUp className="w-6 h-6 text-brand-600" />
            Wissensdatenbank
          </h2>
          <p className="text-slate-500 mt-1">
            Durchsuche {allItems.length} Einträge und {allStrategies.length} Strategie-Impulse aus deiner Historie.
          </p>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4 sticky top-20 z-40">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
          <input 
            type="text" 
            placeholder="Suche nach Themen (z.B. 'Ethik', 'Unterricht', 'Modell')..." 
            className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="relative min-w-[200px]">
          <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
          <select 
            className="w-full pl-10 pr-8 py-2 border border-slate-300 rounded-lg appearance-none bg-white focus:outline-none focus:ring-2 focus:ring-brand-500"
            value={selectedExpertId}
            onChange={(e) => {
                setSelectedExpertId(e.target.value);
                if (e.target.value !== 'all') setViewMode('insights'); // Switch to insights if filtering by expert
            }}
          >
            <option value="all">Alle Experten</option>
            {experts.map(exp => (
              <option key={exp.id} value={exp.id}>{exp.name}</option>
            ))}
          </select>
          <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
        </div>

        <div className="flex bg-slate-100 p-1 rounded-lg">
           <button 
             onClick={() => setViewMode('insights')}
             className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${viewMode === 'insights' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
           >
             News
           </button>
           <button 
             onClick={() => setViewMode('strategy')}
             className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${viewMode === 'strategy' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
           >
             Strategie
           </button>
        </div>
      </div>

      {/* Results Stream */}
      <div className="space-y-4">
        {viewMode === 'insights' ? (
           <>
             {filteredItems.length === 0 ? (
               <div className="text-center py-12 text-slate-400">Keine Einträge für diese Filterkriterien gefunden.</div>
             ) : (
               filteredItems.map((item, idx) => (
                 <div key={idx} className="bg-white p-6 rounded-xl border border-slate-200 hover:border-brand-300 transition-colors shadow-sm">
                    <div className="flex justify-between items-start mb-2">
                       <div className="flex items-center gap-2">
                          <span className="font-bold text-slate-800 text-sm">{item.expertName}</span>
                          <span className="text-slate-300">•</span>
                          <span className="text-xs text-slate-500 flex items-center gap-1">
                             <Calendar className="w-3 h-3" />
                             {new Date(item.date).toLocaleDateString('de-DE')}
                          </span>
                       </div>
                       <a 
                         href={item.sourceUrl} 
                         target="_blank" 
                         rel="noopener noreferrer"
                         className="text-xs font-medium text-brand-600 bg-brand-50 px-2 py-1 rounded hover:bg-brand-100"
                       >
                         {item.sourceName || "Quelle"}
                       </a>
                    </div>

                    <h3 className="text-lg font-bold text-slate-900 mb-2 font-serif">
                      <a href={item.sourceUrl} target="_blank" rel="noopener noreferrer" className="hover:text-brand-600 hover:underline">
                        {item.headline}
                      </a>
                    </h3>
                    <p className="text-slate-600 text-sm leading-relaxed mb-3">
                      {item.summary}
                    </p>
                    <div className="text-[10px] text-slate-400 uppercase tracking-wider">
                       Gefunden im Report: {item.reportTitle}
                    </div>
                 </div>
               ))
             )}
           </>
        ) : (
           <>
              {filteredStrategies.length === 0 ? (
                <div className="text-center py-12 text-slate-400">Keine Strategie-Impulse gefunden.</div>
              ) : (
                <div className="grid gap-4">
                  {filteredStrategies.map((step, idx) => (
                    <div key={idx} className="bg-slate-50 border-l-4 border-brand-500 p-5 rounded-r-xl shadow-sm">
                       <div className="flex items-center gap-2 mb-2 text-xs text-slate-500">
                          <FileText className="w-3 h-3" />
                          Generiert am {new Date(step.date).toLocaleDateString('de-DE')}
                       </div>
                       <p className="text-slate-800 font-medium leading-relaxed">
                         {step.text}
                       </p>
                    </div>
                  ))}
                </div>
              )}
           </>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ExpertList } from './components/ExpertList';
import { Newsletter } from './components/Newsletter';
import { KnowledgeBase } from './components/KnowledgeBase';
import { generateResearchReport } from './services/geminiService';
import { Expert, Report, AppState } from './types';
import { INITIAL_EXPERTS } from './constants';
import { Bot, Library, Sparkles, Play, CalendarClock } from 'lucide-react';

// Simple persistence helper
const loadState = (): AppState => {
  const saved = localStorage.getItem('ai_scout_state_v1');
  if (saved) {
    const parsed = JSON.parse(saved);
    if (!parsed.experts || parsed.experts.length === 0) {
        parsed.experts = INITIAL_EXPERTS;
    }
    return parsed;
  }
  return {
    experts: INITIAL_EXPERTS,
    reports: [],
    isGenerating: false,
    progressMessage: ''
  };
};

export default function App() {
  const [state, setState] = useState<AppState>(loadState());
  const [activeTab, setActiveTab] = useState<'dashboard' | 'experts' | 'archive'>('dashboard');

  // Persist state changes
  useEffect(() => {
    localStorage.setItem('ai_scout_state_v1', JSON.stringify(state));
  }, [state]);

  const handleUpdateExperts = (experts: Expert[]) => {
    setState(prev => ({ ...prev, experts }));
  };

  const handleResetExperts = () => {
    if(confirm("Dies setzt deine Expertenliste auf die Standard-Liste (21 Forscher) zurück. Deine eigenen Änderungen gehen verloren. Fortfahren?")) {
        setState(prev => ({ ...prev, experts: INITIAL_EXPERTS }));
    }
  }

  const handleRunResearch = async () => {
    if (state.isGenerating) return;

    setState(prev => ({ ...prev, isGenerating: true, progressMessage: 'Initialisiere...' }));

    try {
      const report = await generateResearchReport(state.experts, (msg) => {
        setState(prev => ({ ...prev, progressMessage: msg }));
      });

      setState(prev => ({
        ...prev,
        isGenerating: false,
        reports: [report, ...prev.reports]
      }));
      setActiveTab('dashboard');
    } catch (e) {
      setState(prev => ({
        ...prev,
        isGenerating: false,
        progressMessage: 'Fehler aufgetreten.'
      }));
      alert("Es gab ein Problem bei der Recherche. Bitte überprüfe deinen API Key oder versuche es später noch einmal.");
    }
  };

  const latestReport = state.reports[0];

  // Check if report is due (older than 2 days)
  const isUpdateDue = !latestReport || (Date.now() - new Date(latestReport.createdAt).getTime()) > (1000 * 60 * 60 * 24 * 2);

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900 font-sans">
      {/* Header */}
      <header className="bg-slate-900 text-white sticky top-0 z-50 shadow-md">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-brand-500 rounded-lg flex items-center justify-center">
              <Bot className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-lg tracking-tight">AI Scout</span>
          </div>

          <nav className="flex gap-1">
            <button 
              onClick={() => setActiveTab('dashboard')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'dashboard' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Dashboard
            </button>
            <button 
              onClick={() => setActiveTab('experts')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'experts' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Experten ({state.experts.length})
            </button>
            <button 
              onClick={() => setActiveTab('archive')} 
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'archive' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              <span className="flex items-center gap-1">
                Wissensdatenbank
              </span>
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8">

        {/* Progress Overlay */}
        {state.isGenerating && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center z-[100] text-white">
            <div className="w-16 h-16 border-4 border-brand-500 border-t-transparent rounded-full animate-spin mb-6"></div>
            <h2 className="text-2xl font-bold mb-2">Deep Research läuft...</h2>
            <p className="text-slate-300 animate-pulse">{state.progressMessage}</p>
            <div className="mt-8 max-w-md text-center text-sm text-slate-400">
              Der Agent scannt Papers, Social Media und News der {state.experts.filter(e => e.active).length} Experten. Dies kann bis zu 60 Sekunden dauern.
            </div>
          </div>
        )}

        {/* Dashboard View */}
        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            {/* Status / Action Bar */}
            <div className={`flex flex-col md:flex-row md:items-center justify-between gap-6 p-6 rounded-xl border shadow-sm ${isUpdateDue ? 'bg-amber-50 border-amber-200' : 'bg-white border-slate-200'}`}>
              <div>
                <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                  {isUpdateDue ? (
                    <>
                      <CalendarClock className="w-6 h-6 text-amber-600" />
                      Zeit für ein Update!
                    </>
                  ) : (
                    <>Willkommen zurück.</>
                  )}
                </h1>
                <p className={`mt-1 ${isUpdateDue ? 'text-amber-800' : 'text-slate-500'}`}>
                  {isUpdateDue 
                    ? `Dein letzter Report ist ${latestReport ? 'älter als 2 Tage' : 'noch nicht vorhanden'}. Starte jetzt, um auf dem Laufenden zu bleiben.`
                    : `Du bist aktuell. Letztes Update: ${new Date(latestReport.createdAt).toLocaleDateString()}`
                  }
                </p>
              </div>

              <button 
                onClick={handleRunResearch}
                disabled={state.isGenerating}
                className={`${isUpdateDue ? 'bg-amber-600 hover:bg-amber-700 shadow-amber-500/30' : 'bg-brand-600 hover:bg-brand-700 shadow-brand-500/30'} text-white px-8 py-4 rounded-xl font-bold text-lg shadow-lg transition-all flex items-center gap-3 transform hover:-translate-y-1`}
              >
                {state.isGenerating ? (
                  <>Recherchiere...</>
                ) : (
                  <>
                    <Sparkles className="w-5 h-5" />
                    {isUpdateDue ? 'Jetzt Update holen' : 'Deep Research starten'}
                  </>
                )}
              </button>
            </div>

            {/* Latest Report */}
            {latestReport ? (
              <Newsletter report={latestReport} />
            ) : (
              <div className="text-center py-20 bg-white rounded-xl border border-dashed border-slate-300">
                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-slate-100 mb-4">
                  <Play className="w-8 h-8 text-slate-400 ml-1" />
                </div>
                <h3 className="text-xl font-medium text-slate-900 mb-2">Bereit für den ersten Scan</h3>
                <p className="text-slate-500 max-w-md mx-auto mb-6">
                  Wir durchsuchen das Netz nach den 21 Experten deiner Liste.
                </p>
                <button onClick={handleRunResearch} className="text-brand-600 font-medium hover:underline">
                  Jetzt Suche starten
                </button>
              </div>
            )}
          </div>
        )}

        {/* Experts Tab */}
        {activeTab === 'experts' && (
          <div className="max-w-3xl mx-auto space-y-4">
            <div className="flex justify-end">
                <button onClick={handleResetExperts} className="text-xs text-slate-400 hover:text-red-600 underline">
                    Liste auf Standard (21) zurücksetzen
                </button>
            </div>
            <ExpertList experts={state.experts} setExperts={handleUpdateExperts} />
          </div>
        )}

        {/* Knowledge Base / Archive Tab */}
        {activeTab === 'archive' && (
          <div className="max-w-5xl mx-auto">
             <KnowledgeBase reports={state.reports} experts={state.experts} />
          </div>
        )}

      </main>
    </div>
  );
}

export interface Expert {
  id: string;
  name: string;
  role: string;
  topics: string[];
  twitterHandle?: string;
  active: boolean;
}

export interface ReportItem {
  headline: string;
  summary: string;
  sourceUrl: string;
  sourceName: string; // e.g. "Heise", "New York Times", "YouTube - Lex Fridman"
  sourceType: 'Twitter/X' | 'Paper' | 'Video/YouTube' | 'Podcast' | 'News' | 'LinkedIn' | 'Andere';
  expertName: string;
  date: string;
  tags: string[]; // New field for categorization
}

export interface Report {
  id: string;
  createdAt: string;
  title: string;
  intro: string;
  items: ReportItem[];
  actionSteps: string[];
  rawMarkdown: string; 
}

export interface AppState {
  experts: Expert[];
  reports: Report[];
  isGenerating: boolean;
  progressMessage: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Expert, Report } from '../types';

// Initialize Gemini
const getClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateResearchReport = async (
  experts: Expert[],
  onProgress: (msg: string) => void
): Promise<Report> => {
  const ai = getClient();
  const activeExperts = experts.filter(e => e.active);
  const expertNames = activeExperts.map(e => `${e.name} (${e.role})`).join(", ");

  onProgress("Analysiere Bildungskontext & starte Validierung...");

  const modelId = "gemini-3-pro-preview";

  const systemPrompt = `
    Du bist ein präziser Recherche-Agent für einen **Schulleiter und IT-Koordinator**.

    OBERSTE PRIORITÄT: **FAKTENTREUE & FUNKTIONIERENDE QUELLEN**.
    Du darfst NIEMALS URLs erfinden. Nutze AUSSCHLIESSLICH die Links, die das Google Search Tool dir liefert. Wenn du keinen direkten Link hast, nimm das Item nicht auf.

    DEIN NUTZER:
    - Koordiniert IT & Schulentwicklung.
    - Braucht BELEGE für Diskussionen im Kollegium/Schulamt.
    - Will wissen: Wer sagt das? (Spiegel, Heise, OpenAI, Arxiv, persönlicher Tweet?)

    AUFGABE:
    Recherchiere die Aktivitäten der Experten.

    QUELLEN-ANALYSE:
    - Differenziere genau: Ist es ein Blogpost? Ein Paper? Ein YouTube Video?
    - Extrahiere den NAMEN der Quelle (z.B. "Tagesschau", "OpenAI Research Blog", "YouTube - Kanal XYZ").

    TAGGING (SCHLAGWORTE):
    - Generiere für jeden Eintrag 3-5 prägnante Tags.
    - Nutze Begriffe wie: "Ethik", "Datenschutz", "LLM", "Unterrichtspraxis", "Hardware", "Zukunftsvision", "Regulierung", "Schulmanagement".

    ACTION STEPS:
    - Strategisch für Schule & Karriere.
  `;

  const userPrompt = `
    Experten: ${expertNames}

    1. Suche nach NEUEN Aktivitäten (letzte 7 Tage).
    2. Suche nach ZITATEN in Fachmedien (z.B. "Was sagt die Presse zu Hintons neuer Warnung?").
    3. Überprüfe jeden Link: Führt er zur Quelle?

    Erstelle einen Report mit 5-8 Items.
    WICHTIG: Das Feld "sourceName" muss den konkreten Namen der Website/Publikation enthalten (z.B. "Zeit Online", "Arxiv.org", "TechCrunch").
    Das Feld "sourceUrl" muss der exakte Link sein.
  `;

  onProgress("Deep Search: Prüfe Quellen auf Verifizierbarkeit...");

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: userPrompt,
      config: {
        systemInstruction: systemPrompt,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            intro: { type: Type.STRING },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  headline: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING, description: "EXAKTE URL aus dem Suchergebnis." },
                  sourceName: { type: Type.STRING, description: "Name der Publikation/Plattform (z.B. 'Süddeutsche Zeitung', 'OpenAI Blog')" },
                  sourceType: { type: Type.STRING, enum: ["Twitter/X", "Paper", "Video/YouTube", "Podcast", "News", "LinkedIn", "Andere"] },
                  expertName: { type: Type.STRING },
                  date: { type: Type.STRING },
                  tags: { 
                    type: Type.ARRAY, 
                    items: { type: Type.STRING }, 
                    description: "3-5 Schlagworte zur Kategorisierung (z.B. 'Ethik', 'LLM')" 
                  }
                },
                required: ["headline", "summary", "sourceType", "sourceName", "sourceUrl", "expertName", "tags"]
              }
            },
            actionSteps: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["title", "intro", "items", "actionSteps"]
        }
      }
    });

    onProgress("Verarbeite Daten und erstelle Report...");

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText);

    const report: Report = {
      id: crypto.randomUUID(),
      createdAt: new Date().toISOString(),
      title: data.title || "AI Education Update",
      intro: data.intro || "Zusammenfassung der relevanten Entwicklungen.",
      items: data.items || [],
      actionSteps: data.actionSteps || [],
      rawMarkdown: "N/A"
    };

    onProgress("Fertig!");
    return report;

  } catch (error) {
    console.error("Gemini Error:", error);
    onProgress("Fehler beim Abrufen der Daten.");
    throw error;
  }
};

