export const Newsletter: React.FC<NewsletterProps> = ({ report }) => {
  const contentRef = useRef<HTMLDivElement>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);

  const copyToClipboard = () => {
    if (contentRef.current) {
      const html = contentRef.current.innerHTML;
      const blob = new Blob([html], { type: 'text/html' });
      const item = new ClipboardItem({ 'text/html': blob });
      navigator.clipboard.write([item]).then(() => {
        alert("Newsletter HTML kopiert!");
      });
    }
  };

  const handleMailTo = () => {
    const subject = encodeURIComponent(report.title);
    const body = encodeURIComponent(`KI Update:\n\n${report.intro}`);
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  const handlePlayAudio = async () => {
    if (isPlaying) return;
    setIsPlaying(true);
    try {
        await playReportAudio(report);
    } catch (e) {
        console.error(e);
        alert("Fehler bei der Audio-Wiedergabe.");
    } finally {
        setIsPlaying(false);
    }
  };

  const handleExportPDF = async () => {
    if (!contentRef.current) return;

    setIsExporting(true);
    try {
      const element = contentRef.current;

      // Generate canvas from DOM
      const canvas = await html2canvas(element, {
        scale: 2, // Higher scale for better quality
        useCORS: true, // Handle images from external sources if any
        logging: false
      });

      const imgData = canvas.toDataURL('image/png');

      // A4 dimensions in mm
      const pdfWidth = 210;
      const pdfHeight = 297;

      // Calculate image dimensions to fit PDF width
      const imgPropsWidth = pdfWidth;
      const imgPropsHeight = (canvas.height * pdfWidth) / canvas.width;

      const doc = new jsPDF('p', 'mm', 'a4');

      let heightLeft = imgPropsHeight;
      let position = 0;

      // Add first page
      doc.addImage(imgData, 'PNG', 0, position, imgPropsWidth, imgPropsHeight);
      heightLeft -= pdfHeight;

      // Add subsequent pages if content is long
      while (heightLeft >= 0) {
        position = heightLeft - imgPropsHeight;
        doc.addPage();
        doc.addImage(imgData, 'PNG', 0, position, imgPropsWidth, imgPropsHeight);
        heightLeft -= pdfHeight;
      }

      const dateStr = new Date(report.createdAt).toISOString().split('T')[0];
      doc.save(`AI-Scout-Report_${dateStr}.pdf`);
    } catch (error) {
      console.error("PDF Export failed:", error);
      alert("Der PDF Export ist fehlgeschlagen.");
    } finally {
      setIsExporting(false);
    }
