// Helper for time formatting
const formatTime = (seconds: number) => {
    if (!seconds || isNaN(seconds)) return "00:00";
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
};

export const Newsletter: React.FC<NewsletterProps> = ({ report }) => {
  const contentRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const [isExporting, setIsExporting] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [selectedVoice, setSelectedVoice] = useState('Fenrir');

  // Player State
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);

  useEffect(() => {
    // Cleanup URL on unmount
    return () => {
      if (audioUrl) URL.revokeObjectURL(audioUrl);
    };
  }, [audioUrl]);

  const copyToClipboard = () => {
    if (contentRef.current) {
      const html = contentRef.current.innerHTML;
      const blob = new Blob([html], { type: 'text/html' });
      const item = new ClipboardItem({ 'text/html': blob });
      navigator.clipboard.write([item]).then(() => {
        alert("Newsletter HTML kopiert!");
      });
    }
  };

  const handleMailTo = () => {
    const subject = encodeURIComponent(report.title);
    const body = encodeURIComponent(`KI Update:\n\n${report.intro}`);
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  const handleInitializeAudio = async () => {
    if (audioUrl) return; // Already generated

    setIsGeneratingAudio(true);
    try {
        const url = await getReportAudioUrl(report, selectedVoice);
        setAudioUrl(url);
        // Auto play after generation
        setTimeout(() => {
            if (audioRef.current) {
                audioRef.current.play();
                setIsPlaying(true);
            }
        }, 100);
    } catch (e) {
        console.error(e);
        alert("Fehler bei der Audio-Generierung.");
    } finally {
        setIsGeneratingAudio(false);
    }
  };

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleStop = () => {
    if (!audioRef.current) return;
    audioRef.current.pause();
    audioRef.current.currentTime = 0;
    setIsPlaying(false);
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!audioRef.current) return;
    const time = parseFloat(e.target.value);
    audioRef.current.currentTime = time;
    setCurrentTime(time);
