/**
 * Fetches the audio data and returns a Blob URL representing a WAV file.
 * This allows using the native <audio> element for full control.
 */
export const getReportAudioUrl = async (report: Report, voiceName: string = 'Fenrir'): Promise<string> => {
  const ai = getClient();

  // For audio, we summarize the long intro slightly to fit audio constraints, 
  // but keep it substantial.
  const textToRead = `
    Willkommen zu deinem AI Scout Update: ${report.title}. 

    Hier ist die Analyse der Woche:
    ${report.intro}

    Kommen wir nun zu den detaillierten Meldungen. Wir haben ${report.items.length} Updates gefunden.
    Hier sind die wichtigsten:
    ${report.items.slice(0, 5).map(item => `${item.headline} von ${item.expertName}`).join('. ')}.

    Und viele weitere Themen im schriftlichen Report.
    Viel Erfolg bei der Umsetzung.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: {
      parts: [{ text: textToRead }]
    },
    config: {
      responseModalities: ["AUDIO"],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voiceName }
        }
      }
    }
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Kein Audio generiert");

  // Create WAV container
  const pcmData = base64ToInt16Array(base64Audio);
  const sampleRate = 24000;
  const numChannels = 1;
  const bitsPerSample = 16;

  const header = createWavHeader(sampleRate, numChannels, bitsPerSample, pcmData.byteLength);

  // Combine header and data
  const wavBytes = new Uint8Array(header.length + pcmData.byteLength);
  wavBytes.set(header);
  wavBytes.set(new Uint8Array(pcmData.buffer), header.length);

  // Create Blob
  const blob = new Blob([wavBytes], { type: 'audio/wav' });
  return URL.createObjectURL(blob);
};

