// Helper for time formatting
const formatTime = (seconds: number) => {
    if (!seconds || isNaN(seconds)) return "00:00";
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
};

export const Newsletter: React.FC<NewsletterProps> = ({ report }) => {
  const contentRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const [isExporting, setIsExporting] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [selectedVoice, setSelectedVoice] = useState('Fenrir');

  // Player State
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);

  useEffect(() => {
    // Cleanup URL on unmount
    return () => {
      if (audioUrl) URL.revokeObjectURL(audioUrl);
    };
  }, [audioUrl]);

  const copyToClipboard = () => {
    if (contentRef.current) {
      const html = contentRef.current.innerHTML;
      const blob = new Blob([html], { type: 'text/html' });
      const item = new ClipboardItem({ 'text/html': blob });
      navigator.clipboard.write([item]).then(() => {
        alert("Newsletter HTML kopiert!");
      });
    }
  };

  const handleMailTo = () => {
    const subject = encodeURIComponent(report.title);
    const body = encodeURIComponent(`KI Update:\n\n${report.intro}`);
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  const handleInitializeAudio = async () => {
    if (audioUrl) return; // Already generated

    setIsGeneratingAudio(true);
    try {
        const url = await getReportAudioUrl(report, selectedVoice);
        setAudioUrl(url);
        // Auto play after generation
        setTimeout(() => {
            if (audioRef.current) {
                audioRef.current.play();
                setIsPlaying(true);
            }
        }, 100);
    } catch (e) {
        console.error(e);
        alert("Fehler bei der Audio-Generierung. Möglicherweise ist der Text zu lang für eine einzelne Anfrage.");
    } finally {
        setIsGeneratingAudio(false);
    }
  };

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleStop = () => {
    if (!audioRef.current) return;
    audioRef.current.pause();
    audioRef.current.currentTime = 0;
    setIsPlaying(false);
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!audioRef.current) return;
    const time = parseFloat(e.target.value);
    audioRef.current.currentTime = time;
    setCurrentTime(time);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!audioRef.current) return;
    const vol = parseFloat(e.target.value);
    audioRef.current.volume = vol;
    setVolume(vol);
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
    }
  };

  const handleLoadedMetadata = () => {
    if (audioRef.current) {
      setDuration(audioRef.current.duration);
    }
  };

  const handleEnded = () => {
    setIsPlaying(false);
    setCurrentTime(0);
  };

  const handleExportPDF = async () => {
    if (!contentRef.current) return;

    setIsExporting(true);
    try {
      const element = contentRef.current;
      const canvas = await html2canvas(element, { scale: 2, useCORS: true, logging: false });
      const imgData = canvas.toDataURL('image/png');
      const pdfWidth = 210;
      const pdfHeight = 297;
      const imgPropsWidth = pdfWidth;
      const imgPropsHeight = (canvas.height * pdfWidth) / canvas.width;

      const doc = new jsPDF('p', 'mm', 'a4');
      let heightLeft = imgPropsHeight;
      let position = 0;

      doc.addImage(imgData, 'PNG', 0, position, imgPropsWidth, imgPropsHeight);
      heightLeft -= pdfHeight;

      while (heightLeft >= 0) {
        position = heightLeft - imgPropsHeight;
        doc.addPage();
        doc.addImage(imgData, 'PNG', 0, position, imgPropsWidth, imgPropsHeight);
        heightLeft -= pdfHeight;
      }

      const dateStr = new Date(report.createdAt).toISOString().split('T')[0];
      doc.save(`AI-Scout-Report_${dateStr}.pdf`);
    } catch (error) {
      console.error("PDF Export failed:", error);
      alert("Der PDF Export ist fehlgeschlagen.");
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
      {/* Hidden Audio Element */}
      {audioUrl && (
        <audio
          ref={audioRef}
          src={audioUrl}
          onTimeUpdate={handleTimeUpdate}
          onLoadedMetadata={handleLoadedMetadata}
          onEnded={handleEnded}
        />
      )}

      {/* Toolbar */}
      <div className="bg-slate-50 border-b border-slate-200 p-4 flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-2 text-slate-500 text-sm">
          <Calendar className="w-4 h-4" />
          {new Date(report.createdAt).toLocaleDateString('de-DE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
        </div>

        <div className="flex flex-wrap items-center gap-4 justify-center md:justify-end w-full md:w-auto">
          {/* Audio Player Controls */}
          <div className="flex items-center rounded-xl border border-brand-200 bg-brand-50 p-1.5 gap-2 shadow-sm">
            {!audioUrl ? (
                // Initial State: Voice Selector + Generate Button
                <>
                    <select 
                    value={selectedVoice}
                    onChange={(e) => setSelectedVoice(e.target.value)}
                    className="bg-transparent text-xs font-medium text-brand-700 py-1 pl-1 pr-1 focus:outline-none cursor-pointer border-none"
                    disabled={isGeneratingAudio}
                    >
                    <option value="Fenrir">Fenrir (Tief)</option>
                    <option value="Charon">Charon (Tief)</option>
                    <option value="Puck">Puck (Mittel)</option>
                    <option value="Kore">Kore (Weiblich)</option>
                    <option value="Zephyr">Zephyr (Weiblich)</option>
                    </select>
                    <button 
                    onClick={handleInitializeAudio}
                    disabled={isGeneratingAudio}
                    className="flex items-center gap-1.5 px-3 py-1 text-sm font-bold text-white bg-brand-600 hover:bg-brand-700 transition-colors rounded-lg"
                    >
                    {isGeneratingAudio ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4 fill-current" />}
                    {isGeneratingAudio ? 'Generiere Audio...' : 'Vorlesen'}
                    </button>
                </>
            ) : (
                // Player UI State
                <div className="flex items-center gap-3 px-1">
                    {/* Play/Pause */}
                    <button onClick={togglePlay} className="p-1.5 bg-brand-600 text-white rounded-full hover:bg-brand-700 transition">
                        {isPlaying ? <Pause className="w-4 h-4 fill-current" /> : <Play className="w-4 h-4 fill-current ml-0.5" />}
                    </button>

                    {/* Stop */}
                    <button onClick={handleStop} className="p-1.5 text-brand-700 hover:bg-brand-100 rounded-full transition">
                        <Square className="w-4 h-4 fill-current" />
                    </button>

                    {/* Progress Bar & Time */}
                    <div className="flex flex-col w-32 sm:w-48 gap-1">
                        <input
                            type="range"
                            min="0"
                            max={duration}
                            step="0.1"
                            value={currentTime}
                            onChange={handleSeek}
                            className="w-full h-1.5 bg-brand-200 rounded-lg appearance-none cursor-pointer accent-brand-600"
                        />
                        <div className="flex justify-between text-[10px] text-brand-700 font-mono">
                            <span>{formatTime(currentTime)}</span>
                            <span>{formatTime(duration)}</span>
                        </div>
                    </div>

                    {/* Volume Control */}
                    <div className="flex items-center gap-1 group relative">
                        {volume === 0 ? <VolumeX className="w-4 h-4 text-brand-600" /> : <Volume2 className="w-4 h-4 text-brand-600" />}
                        <input
                            type="range"
                            min="0"
                            max="1"
                            step="0.05"
                            value={volume}
                            onChange={handleVolumeChange}
                            className="w-16 h-1.5 bg-brand-200 rounded-lg appearance-none cursor-pointer accent-brand-600"
                            title={`Lautstärke: ${Math.round(volume * 100)}%`}
                        />
                    </div>
                </div>
            )}
          </div>

          <div className="h-6 w-px bg-slate-200 hidden md:block"></div>

          <div className="flex gap-2">
            <button 
                onClick={handleExportPDF} 
                disabled={isExporting}
                className="p-2 text-slate-500 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 hover:text-brand-600 transition-colors disabled:opacity-50"
                title="Als PDF speichern"
            >
                {isExporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
            </button>
            <button onClick={copyToClipboard} className="p-2 text-slate-500 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 hover:text-brand-600 transition-colors" title="HTML Kopieren">
                <Copy className="w-4 h-4" />
            </button>
            <button onClick={handleMailTo} className="p-2 text-slate-500 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 hover:text-brand-600 transition-colors" title="Per E-Mail teilen">
                <Share2 className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Content */}
      <div ref={contentRef} className="p-8 max-w-4xl mx-auto bg-white">
        <div className="mb-8 border-b-4 border-brand-500 pb-6">
          <h1 className="text-3xl md:text-4xl font-serif font-bold text-slate-900 mb-4">{report.title}</h1>
          <p className="text-lg text-slate-600 italic leading-relaxed font-serif">
            {report.intro}
          </p>
        </div>

        <div className="space-y-12">
          {/* Main News Items */}
          <section>
            <h2 className="text-sm font-bold tracking-wider text-slate-400 uppercase mb-8 border-b border-slate-100 pb-2">Geprüfte Updates</h2>
            <div className="grid gap-10">
              {report.items.map((item, idx) => (
                <article key={idx} className="flex flex-col md:flex-row gap-6 group">

                  {/* Metadata Column */}
                  <div className="md:w-1/4 pt-1 flex flex-col gap-2">
                     <div className="font-bold text-slate-900 text-lg leading-tight">
                        {item.expertName}
                     </div>
                     <div className="text-sm text-slate-500">
                        {new Date(item.date).toLocaleDateString('de-DE')}
                     </div>

                     {/* Precise Source Badge */}
                     <div className="mt-2 flex flex-col gap-2">
                       <a href={item.sourceUrl} target="_blank" rel="noopener noreferrer" className="inline-flex flex-col items-start group-source">
                         <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                            {getSourceIcon(item.sourceType)}
                            Quelle
                         </span>
                         <span className="text-brand-600 font-medium text-sm hover:underline break-words leading-tight">
                            {item.sourceName || "Unbekannte Quelle"}
                         </span>
                       </a>

                       <ValidationBadge status={item.linkStatus} />
                     </div>
                  </div>

                  {/* Content Column */}
                  <div className="md:w-3/4">
                    <h3 className="text-xl font-bold text-slate-900 mb-3 group-hover:text-brand-600 transition-colors font-serif">
                      <a href={item.sourceUrl || '#'} target="_blank" rel="noopener noreferrer" className="flex items-start gap-2">
                        {item.headline}
                      </a>
                    </h3>
                    <p className="text-slate-600 leading-relaxed mb-3">
                      {item.summary}
                    </p>

                    {/* Tags */}
                    {item.tags && item.tags.length > 0 && (
                      <div className="flex flex-wrap gap-2 mb-3">
                        {item.tags.map((tag, tIdx) => (
                          <span key={tIdx} className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-600 uppercase tracking-wide">
                            {tag}
                          </span>
                        ))}
                      </div>
                    )}

                    {/* Verification / Access Link */}
                    {item.sourceUrl && (
                      <div className="flex items-center gap-3 mt-1">
                        <a 
                          href={item.sourceUrl} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className={`inline-flex items-center gap-1 text-xs font-bold uppercase tracking-wide transition-colors ${
                            item.linkStatus === 'paywall' ? 'text-amber-600 hover:text-amber-700' : 'text-slate-400 hover:text-brand-600'
                          }`}
                        >
                          {item.linkStatus === 'paywall' ? <Lock className="w-3 h-3" /> : <LinkIcon className="w-3 h-3" />}
                          {item.linkStatus === 'paywall' ? 'Zum Abo-Artikel' : 'Quelle prüfen'}
                        </a>
                      </div>
                    )}
                  </div>
                </article>
              ))}
            </div>
          </section>

          {/* Strategic Action Steps */}
          {report.actionSteps.length > 0 && (
            <section className="bg-slate-50 rounded-xl p-8 border border-slate-200 shadow-sm mt-10">
              <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-3">
                <div className="flex items-center justify-center w-10 h-10 bg-brand-600 text-white rounded-lg shadow-sm">
                  <FileText className="w-5 h-5" />
                </div>
                <div>
                  <div className="uppercase text-xs font-bold text-slate-400 tracking-wider">Strategie</div>
                  Impulse für Schulleitung & IT
                </div>
              </h2>
              <ul className="grid gap-4">
                {report.actionSteps.map((step, idx) => (
                  <li key={idx} className="flex items-start gap-4 bg-white p-5 rounded-lg border border-slate-100 shadow-sm hover:border-brand-200 transition-colors">
                    <span className="flex-shrink-0 w-8 h-8 rounded-full bg-brand-50 text-brand-700 border border-brand-100 flex items-center justify-center font-bold text-sm">
                      {idx + 1}
                    </span>
                    <span className="text-slate-700 font-medium leading-relaxed pt-1">{step}</span>
                  </li>
                ))}
              </ul>
            </section>
          )}
        </div>

        <div className="mt-12 pt-8 border-t border-slate-200 flex flex-col items-center gap-2">
           <div className="text-slate-400 text-xs uppercase tracking-widest">
            AI Scout Agent • Recherche für Bildung & Führung
          </div>
          <div className="text-slate-300 text-[10px] text-center max-w-lg">
            Quellen werden automatisch auf Paywalls geprüft. Gelbe Markierungen deuten auf kostenpflichtige Inhalte hin.
          </div>
        </div>
      </div>
    </div>
  );
};
